     format!(
         "event: message_start\n\
          data: {{\"type\":\"message_start\",\"message\":{{\"usage\":{{\"input_tokens\":{input},\"cache_read_input_tokens\":{cache_read},\"cache_creation_input_tokens\":{cache_creation},\"output_tokens\":0}}}}}}\n\n\
